const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // Define Bear Island and two points south
  const bearIsland = ee.Geometry.Point([19.0, 74.5]);
  const point100kmS = ee.Geometry.Point([19.0, 70.5]); // ~100 km south
  const point250kmS = ee.Geometry.Point([19.0, 67.0]); // ~250 km south

  // Buffer to 5 km radius for sampling
  const buffer100 = point100kmS.buffer(5000);
  const buffer250 = point250kmS.buffer(5000);

  // Date range (August 5, 2025 - future date)
  const dateStart = '2025-08-05';
  const dateEnd = '2025-08-06';

  // Sentinel-2 collection (L2A - bottom of atmosphere reflectance)
  let col = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
    .filterDate(dateStart, dateEnd)
    .filterBounds(point100kmS.buffer(300000))
    .filter(ee.Filter.lt('CLOUDY_PIXEL_PERCENTAGE', 80)); // Allow some clouds for future date

  const colSize = col.size().getInfo();
  console.log(`Sentinel-2 images found (Aug 5, 2025): ${colSize}`);

  if (colSize === 0) {
    console.log('No Sentinel-2 data for August 5, 2025 (future date or no coverage)');
    console.log('C1');
    return;
  }

  // Mosaic images for the date
  const img = col.median();

  // Select visible bands (B2=Blue, B3=Green, B4=Red) for true color
  const vis = img.select(['B2', 'B3', 'B4']);

  // Calculate turquoise index: (B2 + B3) / B4
  // Higher values = lighter, more "milky" water (sediment-laden)
  const turquoiseIndex = img.select('B2').add(img.select('B3')).divide(img.select('B4'));

  // Measure 1: Mean turquoise index at 100 km south
  const stats100 = turquoiseIndex.reduceRegion({
    reducer: ee.Reducer.mean().combine(ee.Reducer.count(), '', true),
    geometry: buffer100,
    scale: 20,
    maxPixels: 1e9
  }).getInfo();

  const val100 = stats100.B2_B3_B4_mean;
  const count100 = stats100.B2_B3_B4_count;

  console.log(`100 km south - Turquoise Index: ${val100?.toFixed(3) || 'N/A'}, Pixels: ${count100 || 0}`);

  if (count100 === 0 || count100 === undefined) {
    console.log('C2');
    return;
  }

  // Measure 2: Mean turquoise index at 250 km south
  const stats250 = turquoiseIndex.reduceRegion({
    reducer: ee.Reducer.mean().combine(ee.Reducer.count(), '', true),
    geometry: buffer250,
    scale: 20,
    maxPixels: 1e9
  }).getInfo();

  const val250 = stats250.B2_B3_B4_mean;
  const count250 = stats250.B2_B3_B4_count;

  console.log(`250 km south - Turquoise Index: ${val250?.toFixed(3) || 'N/A'}, Pixels: ${count250 || 0}`);

  if (count250 === 0 || count250 === undefined) {
    console.log('C2');
    return;
  }

  // Validation
  if (val100 === null || val100 === undefined || isNaN(val100) || 
      val250 === null || val250 === undefined || isNaN(val250)) {
    console.log('C3');
    return;
  }

  // Compare: higher turquoise index = milkier/lighter color (more sediment)
  const comparison = val100 > val250;

  console.log(`Comparison: 100km (${val100.toFixed(3)}) > 250km (${val250.toFixed(3)}) = ${comparison}`);

  if (comparison) {
    console.log('A');
  } else {
    console.log('B');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
